using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var services = new ServiceCollection();

services.AddHttpClient<ResearchTools>();

services.AddChatClient(builder => builder
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", new OpenAIClient(apiKey)));

var provider = services.BuildServiceProvider();
var chatClient = provider.GetRequiredService<IChatClient>();
var tools = provider.GetRequiredService<ResearchTools>();

var aiTools = new[]
{
    AIFunctionFactory.Create(tools.SearchWeb),
    AIFunctionFactory.Create(tools.SaveNote),
    AIFunctionFactory.Create(tools.GetNotes),
};

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var systemPrompt = """
    You are a research agent. Your job is to thoroughly research a topic and produce
    a well-structured summary. Follow this workflow:

    1. Search the web for information on the topic (run 2-3 different searches
       with varied queries to get broad coverage).
    2. After each search, save important findings as notes using the note-taking tool.
    3. Once you have gathered enough information, retrieve all your notes and
       produce a final, well-organized summary with key findings, important details,
       and any notable perspectives or controversies.

    Be thorough but concise. Cite specific facts when possible.
    """;

var history = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var options = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [.. aiTools],
    ToolMode = ChatToolMode.Auto,
};

const int maxIterations = 15;
var iteration = 0;

while (iteration++ < maxIterations)
{
    var response = await chatClient.GetResponseAsync(history, options);
    history.AddMessages(response);

    // Check if the model made any tool calls
    var toolCalls = response.Messages
        .SelectMany(m => m.Contents.OfType<FunctionCallContent>())
        .ToList();

    if (toolCalls.Count == 0)
    {
        // No more tool calls — final answer
        var answer = response.Messages
            .SelectMany(m => m.Contents.OfType<TextContent>())
            .LastOrDefault()?.Text;

        Console.WriteLine("═══════════════════════════════════════════");
        Console.WriteLine("  RESEARCH SUMMARY");
        Console.WriteLine("═══════════════════════════════════════════\n");
        Console.WriteLine(answer ?? "No summary produced.");
        break;
    }

    // Execute each tool call
    foreach (var call in toolCalls)
    {
        Console.WriteLine($"  🛠  {call.Name}({TruncateArgs(call.Arguments)})");

        var result = await call.InvokeAsync(cancellationToken: default);
        var resultMessage = new ChatMessage(ChatRole.Tool,
        [
            new FunctionResultContent(call.CallId, result),
        ]);
        history.Add(resultMessage);
    }
}

if (iteration > maxIterations)
{
    Console.WriteLine("⚠️  Reached maximum iteration limit.");
}

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input) ? "recent advances in quantum computing" : input;
}

static string TruncateArgs(IDictionary<string, object?>? args)
{
    if (args is null || args.Count == 0) return "";
    var s = string.Join(", ", args.Select(kv => $"{kv.Key}: {kv.Value}"));
    return s.Length > 80 ? s[..77] + "..." : s;
}

// ── Tool definitions ────────────────────────────────────────────────────

public sealed class ResearchTools
{
    private readonly HttpClient _httpClient;
    private readonly List<string> _notes = [];

    public ResearchTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [Description("Search the web for information. Returns text snippets from search results.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://html.duckduckgo.com/html/?q={encoded}";

        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

        var response = await _httpClient.SendAsync(request, cancellationToken);
        response.EnsureSuccessStatusCode();

        var html = await response.Content.ReadAsStringAsync(cancellationToken);
        return ParseSnippets(html);
    }

    [Description("Save a research note. Use this to record important findings.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("Detailed content of the note")] string content)
    {
        _notes.Add($"## {title}\n{content}");
        return $"Note saved: \"{title}\" ({_notes.Count} total notes).";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public string GetNotes()
    {
        return _notes.Count == 0
            ? "No notes saved yet."
            : string.Join("\n\n---\n\n", _notes);
    }

    private static string ParseSnippets(string html)
    {
        var snippets = new List<string>();
        const string marker = "result__snippet";
        var idx = 0;

        while (snippets.Count < 6)
        {
            idx = html.IndexOf(marker, idx, StringComparison.Ordinal);
            if (idx < 0) break;

            var tagClose = html.IndexOf('>', idx);
            if (tagClose < 0) break;

            var contentStart = tagClose + 1;
            var contentEnd = html.IndexOf("</", contentStart, StringComparison.Ordinal);
            if (contentEnd < 0) break;

            var raw = System.Net.WebUtility.HtmlDecode(
                System.Text.RegularExpressions.Regex.Replace(
                    html[contentStart..contentEnd], "<[^>]+>", " ")).Trim();

            if (raw.Length > 20)
                snippets.Add($"- {raw}");

            idx = contentEnd;
        }

        return snippets.Count > 0
            ? string.Join("\n", snippets)
            : "No results found for this query.";
    }
}

